Title: OBJ converted to Three is rendered all in black.
Description: Hi All,

I used convert_obj_three.py (only specified -i & -o).
When rendering the output, everything is in black.
If I use MeshNormalMaterial, rainbow-ish colors are used.
The code is in the below.
(If someone can tell me how to upload OBJ data to this forum, I will post it as well)

So the question is, how do I render the converted OBJ with real textures?

Thanks,
Q

``` html
<script>

    var SCREEN_WIDTH = window.innerWidth;
    var SCREEN_HEIGHT = window.innerHeight;
    var container, stats;
    var camera, scene, webglRenderer;
    var zmesh;

    var mouseX = 0, mouseY = 0;
    var windowHalfX = window.innerWidth / 2;
    var windowHalfY = window.innerHeight / 2;

    document.addEventListener('mousemove', onDocumentMouseMove, false);

    init();
    animate();

    function init() {
        container = document.createElement('div');
        document.body.appendChild(container);

        camera = new THREE.PerspectiveCamera( 75, SCREEN_WIDTH / SCREEN_HEIGHT, 1, 100000);
        camera.position.z = 500;

        scene = new THREE.Scene();

        // RENDERER

        try {
            webglRenderer = new THREE.WebGLRenderer();
            webglRenderer.setSize(SCREEN_WIDTH, SCREEN_HEIGHT);
            webglRenderer.domElement.style.position = "relative";

            container.appendChild(webglRenderer.domElement);

        } catch(e) {
            alert(e.toLocaleString());
        }

        // STATS

        stats = new Stats();
        stats.domElement.style.position = 'absolute';
        stats.domElement.style.top = '0px';
        stats.domElement.zIndex = 100;
        container.appendChild(stats.domElement);

        var loader = new THREE.JSONLoader();
        var callback = function (geometry) {createScene(geometry)};
        loader.load("obj/my_city/my_city_0.js", callback);
    }

    function createScene(geometry) {
        zmesh = new THREE.Mesh(geometry, new THREE.MeshFaceMaterial());
        zmesh.overdraw = true;
        scene.add(zmesh);
    }

    function onDocumentMouseMove(event) {
        mouseX = (event.clientX - windowHalfX);
        mouseY = (event.clientY - windowHalfY);
    }

    function animate() {
        requestAnimationFrame(animate);

        render();
        stats.update();
    }

    function render() {
        camera.position.x += (mouseX - camera.position.x) * .05;
        camera.position.y += (-mouseY - camera.position.y) * .05;

        camera.lookAt(scene.position);

        webglRenderer.render(scene, camera);
    }

</script>
